INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x209-protege', 1, 'NG-GR109 Forearm Grenade Launcher (1, right)', 'By grenade type; usually plasma or high explosive', 1, '600 ft (183 m)', 'One at a time or volleys of 2 or 3', '18 grenades', NULL, 'Anti-personnel and anti-armor, secondarily defense and anti-fortification. Housed in a boxy forearm casing styled after the Samson''s tri-barrel laser, so an enemy expects laser fire and gets grenades.'),
  ('ng-x209-protege', 2, 'NG-P209 Forearm Particle Beam Blaster (1, left)', '6D6 M.D.', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits. Electric suits get the laser instead, 80 blasts per charge', NULL, 'Anti-monster and anti-armor, secondarily assault and defense. NG long avoided particle beams for their power draw, short reach and overheating, and is trying them again now that the heat problem is partly solved. Point and shoot. A buyer wanting reach can swap it for a single-barrel laser (3D6 M.D., 2,000 ft/610 m), which is also what the electric version carries.'),
  ('ng-x209-protege', 3, 'NG SP209 Forearm Vibro-Sword (1, left)', 'Slash 2D4 M.D.; power strike or stab 3D4 M.D., counting as two melee attacks', 1, 'Melee; 2 ft (0.6 m) beyond arm''s reach', 'Each attack counts as one melee action', 'Effectively unlimited; powered by the suit', NULL, 'Assault and anti-monster, secondarily defense and sabotage. A broad blade in the left forearm housing that still sticks out a foot (0.3 m) past the fist when stowed. Silver plating against the supernatural is 8,000 credits (gear row ng-x209-protege-silver-plating).'),
  ('ng-11f-red-hawk', 1, 'NG-202 Rail Gun', '1D4 M.D. per single round; 3D6 M.D. per 20-round burst; 1D4x10 M.D. per 40-round burst', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack', '2,800-round drum: 140 medium (3D6) or 70 heavy (1D4x10) bursts. A reload takes about 5 minutes untrained, about 90 seconds for someone trained in power armor', NULL, 'Assault, secondarily defense. The standard NG-202 as the suit''s main gun, powered by its reactor and fed from a drum on its back.'),
  ('ng-11f-red-hawk', 2, 'Wing Mounted Mini-Missile Launchers', 'By missile; standard issue armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.), but any mini-missile fits', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6', '12, six per wing', NULL, 'Anti-aircraft, secondarily air-to-ground assault. Up to six mini-missiles hang from each wing, mostly for fights with other aircraft and strikes on surface targets.'),
  ('ng-11f-red-hawk', 3, 'Forearm Ranged Weapon (1 or 2; laser or mini-missile launcher)', 'Laser 2D6+1 M.D.; mini-missile by type, standard issue armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'Laser 1,000 ft (305 m); mini-missile one mile (1.6 km)', 'Laser: one blast or two at once, either counting as one melee attack. Mini-missiles: one at a time or a volley of two', 'Laser effectively unlimited, drawing on the suit''s power; two missiles per launcher, two launchers at most', NULL, 'Anti-armor, secondarily assault. Either weapon goes on one or both forearms; the two-shot launcher is the same one the NG Samson carries.'),
  ('ng-11f-red-hawk', 4, 'Scythe-Forearm Vibro-Blades (2)', '2D4 M.D. per strike at cruising speed or slower; 4D4 M.D. at 61-150 mph (97.6 to 240 km); 5D6 M.D. faster still', 1, 'Melee', 'Hand to hand; a dive attack counts as two melee attacks', NULL, NULL, 'Anti-power armor, secondarily defense. One curved blade extends from and retracts into each forearm, for hand to hand and fast slashing passes. A missed strike at speed means a piloting roll at -30%; failing it, the Red Hawk crashes into its target or whatever is near (an ally, aircraft, wall, tree, the ground) and takes 1D10 M.D. per 100 mph (160 km) of speed.'),
  ('ng-uelx42-sabre', 1, 'Vibro-Saber (handheld)', '2D4 M.D.', 1, 'Melee; about 2 ft (0.6 m) beyond arm''s reach', NULL, NULL, NULL, 'Assault, secondarily defense. A Vibro-Saber, or short sword, comes standard with the suit, hung from a belt in its scabbard; no separate price is printed.'),
  ('ng-x13-samson-missileman', 1, 'NG-S202 Super-Samson Rail Gun', '1D6 M.D. per single round; 1D6x10 M.D. per 60-round burst', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack', '6,000-round drum for 100 bursts. A reload takes about five minutes untrained, one minute for someone trained in power armor', NULL, 'Assault, secondarily defense. The suit''s standard infantry gun, powered by its reactor and fed from a drum on its back.'),
  ('ng-x13-samson-missileman', 2, 'SM113 Scissor Short-Range Missile Launchers (2; back)', 'By missile; standard issue armor piercing (2D6x10 M.D. to a 5 ft/1.5 m radius) or plasma (2D6x10 M.D. to a 15 ft/4.6 m radius)', 1, 'Five miles (8 km)', 'One at a time or volleys of 2, 4, 6 or 8', '10, five per arm', NULL, 'Anti-armor and anti-dragon, secondarily anti-aircraft and assault. Like the NG-M56 Multi-Bot''s: two five-shot arms that swing up and lock in a V to fire.'),
  ('ng-x13-samson-missileman', 3, 'NG-SM24 Shoulder Mini-Missile Launchers (2)', 'By missile; standard issue armor piercing (1D4x10 M.D.) and/or plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4, 6, 8 or 12', '24, 12 per shoulder', NULL, 'Anti-aircraft, secondarily assault and defense. Large armored housings on the shoulders, refitted in spring 109 P.A. to hold 12 current-model mini-missiles each.'),
  ('ng-x13-samson-missileman', 4, 'NG-SAM209 Forearm Mini-Missile Launcher (1-2; left or both forearms)', 'By missile', 1, 'One mile (1.6 km)', 'One at a time or a volley of two', 'Four, two in each of its two barrels; eight with a launcher on the right forearm too, which is rare', NULL, 'Anti-aircraft and anti-missile, secondarily anti-armor and defense. An old-style double-barrel launcher in the left forearm. The Mk I had one on each arm and no Tri-Laser; now one or both are often traded for the Tri-Laser so the suit has a weapon that is not a missile.'),
  ('ng-x13-samson-missileman', 5, 'NG-SAM309 Forearm Tri-Laser (optional; replaces a forearm launcher)', '2D6 M.D. single, 4D6 M.D. dual, 6D6 M.D. triple blast at one target', 1, '1,600 ft (488 m)', 'Each single or multiple blast counts as one melee attack', 'Effectively unlimited; powered by the suit', NULL, 'Assault and anti-personnel, secondarily defense. Barrel-less: it fires from three openings in a forearm plate that looks like a small shield, and is usually mistaken for the missile launcher.'),
  ('ng-x13-samson-missileman', 6, 'Knuckle Vibro-Blades', '3D4+3 M.D., Robot P.S. included', 1, 'Melee; arm''s reach, about 5 ft (1.5 m)', NULL, NULL, NULL, 'Assault and close combat, secondarily defense. Three wicked blades extend from the hand.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-x209-protege', 'ng-11f-red-hawk', 'ng-uelx42-sabre', 'ng-x13-samson-missileman');
SELECT 'their 43 locations are in' AS assertion, count(*) AS got, 43 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x209-protege', 'ng-11f-red-hawk', 'ng-uelx42-sabre', 'ng-x13-samson-missileman');
SELECT 'their 14 weapon entries are in' AS assertion, count(*) AS got, 14 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x209-protege', 'ng-11f-red-hawk', 'ng-uelx42-sabre', 'ng-x13-samson-missileman');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x209-protege', 'ng-11f-red-hawk', 'ng-uelx42-sabre', 'ng-x13-samson-missileman') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~311-northern-gun-2-power-armor-g.sql');
